// Sphere merged with tori: one more torus for every step of E, up to six.
// The six seats are the half-axes +X, -X, +Y, -Y, +Z, -Z, taken in that order,
// so E = 2 gives the pair on X, E = 4 adds the pair on Y, E = 6 closes with Z.
E := int(1,6);

float n = max(floor(E + 0.5), 1.0);

float d = length(p) - A;                  // the sphere

// The script body is wrapped into a single function and cannot declare helpers
// of its own, so the seats are walked with a loop instead of six copies.
// int(0.0)/int(6.0): the auto-formatter needs the bounds written this way.
for (int k = int(0.0); k < int(6.0); k++) {
    float fk = float(k);
    if (fk >= n) break;                   // only the first E seats are drawn

    // seat -> axis (0 = X, 1 = Y, 2 = Z) and sign (+1 on even k, -1 on odd)
    float axis = floor(fk * 0.5);
    float sgn  = (mod(fk, 2.0) < 0.5) ? 1.0 : -1.0;

    // c = coordinate along the torus axis, u and v = the other two
    float c = (axis < 0.5) ? p.x : ((axis < 1.5) ? p.y : p.z);
    float u = (axis < 0.5) ? p.y : ((axis < 1.5) ? p.z : p.x);
    float v = (axis < 0.5) ? p.z : ((axis < 1.5) ? p.x : p.y);

    float ring = sqrt((c - sgn * D) * (c - sgn * D) + u * u) - B;
    d = min(d, sqrt(ring * ring + v * v) - C);
}
return d;
